"""Exactly two v2 evaluations, after common freeze and complete16/39 inference."""
from pathlib import Path
import argparse,json,sys,importlib,datetime
from common import read,ref,save
from assemble import ENDPOINTS,checked

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--plan',required=True);ap.add_argument('--freeze',required=True);ap.add_argument('--output',required=True);a=ap.parse_args();p=json.loads(Path(a.plan).read_text());freeze=json.loads(Path(a.freeze).read_text());assert freeze['status']=='BOTH_COMPLETE_PREDICTIONS_FROZEN_NO_QUALITY' and set(freeze['endpoints'])==set(ENDPOINTS) and freeze['all_baseline_relations_preserved_primary'] and freeze['all_nonphenotype_objects_preserved'];assert freeze['plan']==ref(a.plan);refs=p['quality_refs'];checked(refs['evaluator']);checked(refs['validator']);sys.path.insert(0,str(Path(refs['evaluator']['path']).parent));ev=importlib.import_module('evaluate');va=importlib.import_module('validate_predictions');assert ev.VERSION=='patientphex-public-approx-v2';base=va.load_jsonl(checked(p['baseline']));old=json.loads(checked(p['baseline_metrics']).read_text())['metrics'];assert old['Score']==p['quality']['baseline_score'];inp=va.load_jsonl(checked(refs['input']));hpo=va.read_hpo(checked(refs['hpo']));pred={n:va.load_jsonl(checked(freeze['endpoints'][n])) for n in ENDPOINTS};formats={n:va.validate_predictions(inp,d,hpo) for n,d in pred.items()};assert all(v['valid'] for v in formats.values());O=Path(a.output);O.mkdir(parents=True,exist_ok=False)
 save(O/'evaluation-intent.json',{'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'plan':ref(a.plan),'joint_freeze':ref(a.freeze),'sources':{n:ref(Path(__file__).with_name(n)) for n in ['quality.py','assemble.py']},'new_v2':2,'old_v2':0,'single_patient_v2':0,'originaldev':False});gold=va.load_jsonl(checked(refs['gold']))
 def pairs(ds):return {(str(d['pmc_id']),pid,c) for d in ds for pid,cs in ev.associations(d).items() for c in cs}
 goldpairs=pairs(gold);basepairs=pairs(base);out={}
 for n in ENDPOINTS:
  sub=O/n;sub.mkdir();m=ev.evaluate_report(gold,pred[n],body_scope='all',no_id_doc='text');m['prediction_sha256']=freeze['endpoints'][n]['sha256'];m['gold_sha256']=refs['gold']['sha256'];save(sub/'metrics.json',m);save(sub/'format.json',formats[n]);ps=pairs(pred[n]);added=ps-basepairs;removed=basepairs-ps;delta={k:m['metrics'][k]-old[k] for k in old};out[n]={'metrics':m['metrics'],'delta':delta,'prediction':freeze['endpoints'][n],'metrics_file':ref(sub/'metrics.json'),'format':ref(sub/'format.json'),'relations':len(ps),'added':len(added),'added_TP':len(added&goldpairs),'added_FP':len(added-goldpairs),'removed':len(removed),'removed_TP':len(removed&goldpairs),'removed_FP':len(removed-goldpairs),'strictly_above_B':delta['Score']>0}
 best=max(ENDPOINTS,key=lambda n:out[n]['metrics']['Score']);save(O/'result.json',{'status':'COMPLETE_FIXED_TWO_ENDPOINTS_PATIENT_SPANS_F1_DEVELOPMENT','baseline':old,'endpoints':out,'primary_success':out[ENDPOINTS[0]]['strictly_above_B'],'retain_any':out[best]['strictly_above_B'],'best_fixed_endpoint':best,'new_v2':2,'old_v2':0,'single_patient_v2':0,'not_blind':True,'originaldev':False,'official':False,'plan':ref(a.plan),'joint_freeze':ref(a.freeze)});print(json.dumps({n:v['metrics'] for n,v in out.items()}),flush=True)
if __name__=='__main__':main()
